import base64, dataclasses, time, glob, gc
open("/kaggle/working/attack_lr.py","wb").write(base64.b64decode(""))
import importlib.util
_spec = importlib.util.spec_from_file_location("attack_lr","/kaggle/working/attack_lr.py")
_mod = importlib.util.module_from_spec(_spec); _spec.loader.exec_module(_mod)
AttackAlgorithm = _mod.AttackAlgorithm
from kaggle_evaluation.jed_attack_134815 import gpt_oss_model_server, gemma_model_server
from kaggle_evaluation.jed_attack_134815.gguf_model_server import GgufModelServer
from aicomp_sdk.core.env.api import EnvSelection
from aicomp_sdk.evaluation.runner import evaluate_redteam
def _fx():
    for c in glob.glob("/kaggle/input/**/aicomp_sdk/fixtures", recursive=True): return c
    import aicomp_sdk, pathlib; return str(pathlib.Path(aicomp_sdk.__file__).parent/"fixtures")
BUDGET = 1800.0
MAXN = 40   # cap N so replay fits BUDGET on CPU (host partial-preserves; local SDK raises on overrun)
def run(name, base_spec):
    spec = dataclasses.replace(base_spec, n_gpu_layers=0, n_ctx=2048)
    srv = GgufModelServer(spec)
    print(f"[load] {name} ...", flush=True); t=time.time(); srv.load_model(); print(f"[load] {time.time()-t:.0f}s", flush=True)
    fac = lambda: srv._load_agent()
    t0=time.time()
    try:
        ex = evaluate_redteam(AttackAlgorithm, budget_s=BUDGET, agent_factory=fac, agent_label=name+"_gguf",
                              env_selection=EnvSelection.GYM, fixtures_dir=_fx(), attack_env_seed=123,
                              attack_config={"fill_mode":"adaptive_k2","max_n":MAXN})
        a = ex.attack
        print(f"=== [{name}] score={a.score:.3f} raw={a.score_raw} findings={a.findings_count} cells={a.unique_cells} wall={time.time()-t0:.0f}s ===", flush=True)
        res = (a.score, a.findings_count, a.unique_cells)
    except Exception as e:
        print(f"=== [{name}] ERROR: {e!r} (wall={time.time()-t0:.0f}s) ===", flush=True); res=(float('nan'),0,0)
    try: srv.unload()
    except Exception: pass
    gc.collect()
    return res
g = run("gpt_oss", gpt_oss_model_server.SPEC)
m = run("gemma", gemma_model_server.SPEC)
print("\n=== PER-ROW (adaptive_k2, PUBLIC guardrail, MAXN=40 CPU) ===", flush=True)
print(f"  gpt_public:   score={g[0]:.3f}  findings={g[1]}  cells={g[2]}", flush=True)
print(f"  gemma_public: score={m[0]:.3f}  findings={m[1]}  cells={m[2]}", flush=True)
print(f"  per-candidate: gpt raw/finding={ (g[0]*200/g[1]) if g[1] else 0:.1f}  gemma raw/finding={ (m[0]*200/m[1]) if m[1] else 0:.1f}", flush=True)
print("  Diagnose: findings==MAXN? (fire 100%); cells==findings? (cell-maxed); gpt vs gemma raw/finding (34 vs 18 => burst2 vs single).", flush=True)
